1: <!DOCTYPE html>
2: <html lang="en">
3: <head>
4:   <meta charset="UTF-8">
5:   <meta name="viewport" content="width=device-width, initial-scale=1.0">
6:   <title>Create Account — STRIDE Marketplace</title>
7:   <meta name="description" content="Register for a STRIDE collector account to unlock member-only shock drops, 24-hour consignment payouts, and verified authentication certificates.">
8:   <link rel="icon" type="image/svg+xml" href="../assets/logo-mark.svg">
9:   <link rel="stylesheet" href="../css/stride.css">
10:   <style>
11:     .strength-meter {
12:       height: 4px;
13:       background: #292D38;
14:       border-radius: 99px;
15:       margin-top: 0.5rem;
16:       overflow: hidden;
17:     }
18:     .strength-bar {
19:       height: 100%;
20:       width: 0%;
21:       transition: width 0.3s ease, background-color 0.3s ease;
22:     }
23:   </style>
24: </head>
25: <body>
26: 
27:   <!-- Header -->
28:   <header class="stride-header">
29:     <div class="container">
30:       <div class="nav-inner">
31:         <a href="../index.html" class="brand-logo" aria-label="STRIDE Home">
32:           <img src="../assets/logo.svg" alt="STRIDE — Be Your Own" width="160" height="40">
33:         </a>
34: 
35:         <nav class="nav-links">
36:           <a href="../index.html" class="nav-link">Home</a>
37:           <a href="shop.html" class="nav-link">Shop</a>
38:           <a href="sell.html" class="nav-link">Sell Your Sneakers</a>
39:           <a href="about.html" class="nav-link">About</a>
40:         </nav>
41: 
42:         <div class="nav-actions">
43:           <a href="login.html" class="btn btn-secondary btn-sm">Sign In</a>
44:         </div>
45:       </div>
46:     </div>
47:   </header>
48: 
49:   <!-- Sign Up Form Wrapper -->
50:   <div class="auth-wrapper">
51:     <div class="auth-card" style="max-width: 520px;">
52:       <div class="auth-header">
53:         <img src="../assets/logo-mark.svg" alt="STRIDE Mark" width="46" height="46" style="margin: 0 auto 1.25rem;">
54:         <h1>JOIN <span class="text-neon">STRIDE</span></h1>
55:         <p style="font-size: 0.9rem; color: #A0A4AE;">Create your account to unlock verified drops and buyer protection.</p>
56:       </div>
57: 
58:       <form id="signup-form" novalidate>
59:         <div class="form-group" style="margin-bottom: 1.25rem;">
60:           <label class="form-label" for="signup-name">Full Name *</label>
61:           <input type="text" id="signup-name" class="form-input" placeholder="e.g. Elena Rostova" required>
62:           <span class="form-error-msg">Please enter your full name.</span>
63:         </div>
64: 
65:         <div class="form-group" style="margin-bottom: 1.25rem;">
66:           <label class="form-label" for="signup-email">Email Address *</label>
67:           <input type="email" id="signup-email" class="form-input" placeholder="elena@example.com" required>
68:           <span class="form-error-msg">Please enter a valid email address.</span>
69:         </div>
70: 
71:         <div class="form-group" style="margin-bottom: 1.25rem;">
72:           <label class="form-label" for="signup-password">Create Password *</label>
73:           <input type="password" id="signup-password" class="form-input" placeholder="Minimum 8 characters" required>
74:           <div class="strength-meter">
75:             <div class="strength-bar" id="strength-bar"></div>
76:           </div>
77:           <span class="form-error-msg">Password must be at least 8 characters.</span>
78:         </div>
79: 
80:         <div class="form-group" style="margin-bottom: 1.5rem;">
81:           <label class="form-label" for="signup-confirm-password">Confirm Password *</label>
82:           <input type="password" id="signup-confirm-password" class="form-input" placeholder="Re-enter password" required>
83:           <span class="form-error-msg" id="confirm-error-msg">Passwords do not match.</span>
84:         </div>
85: 
86:         <div style="margin-bottom: 1.75rem;">
87:           <label style="display: flex; align-items: flex-start; gap: 0.65rem; font-size: 0.82rem; color: #A0A4AE; cursor: pointer; line-height: 1.5;">
88:             <input type="checkbox" id="terms-agree" required style="accent-color: #FF5A1F; margin-top: 3px;">
89:             <span>I agree to the <a href="faq.html" style="color: #FF5A1F;">STRIDE Terms of Service</a> and verify my compliance with consignment policies.</span>
90:           </label>
91:           <span class="form-error-msg" id="terms-error-msg" style="margin-top: 0.4rem;">You must accept the terms to proceed.</span>
92:         </div>
93: 
94:         <button type="submit" class="btn btn-primary btn-lg btn-block" style="margin-bottom: 1.25rem;">
95:           CREATE COLLECTOR ACCOUNT
96:         </button>
97:       </form>
98: 
99:       <!-- Success Confirmation View -->
100:       <div id="signup-success-view" style="display: none; text-align: center; padding: 2rem 0;">
101:         <div style="width: 60px; height: 60px; border-radius: 50%; background: rgba(255, 90, 31, 0.15); border: 2px solid #FF5A1F; display: flex; align-items: center; justify-content: center; margin: 0 auto 1.25rem;">
102:           <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#FF5A1F" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>
103:         </div>
104:         <h3 style="font-size: 1.4rem; color: #FFFFFF; margin-bottom: 0.5rem;">Account Initialized!</h3>
105:         <p style="font-size: 0.9rem; color: #A0A4AE; margin-bottom: 1.5rem;">Welcome to STRIDE. You are now logged in as a verified member.</p>
106:         <a href="shop.html" class="btn btn-primary btn-block">Explore Grails</a>
107:       </div>
108: 
109:       <div style="text-align: center; border-top: 1px solid #292D38; padding-top: 1.5rem; font-size: 0.88rem; color: #A0A4AE;">
110:         Already registered? <a href="login.html" style="color: #FF5A1F; font-weight: 700;">Sign in to account →</a>
111:       </div>
112:     </div>
113:   </div>
114: 
115:   <!-- Footer -->
116:   <footer class="stride-footer" style="padding: 2.5rem 0;">
117:     <div class="container text-center" style="font-size: 0.82rem; color: #626775;">
118:       &copy; 2026 STRIDE Marketplace Inc. All rights reserved.
119:     </div>
120:   </footer>
121: 
122:   <!-- Scripts -->
123:   <script src="../js/stride-data.js"></script>
124:   <script src="../js/stride-core.js"></script>
125: 
126:   <script>
127:     const pwdInput = document.getElementById('signup-password');
128:     const strengthBar = document.getElementById('strength-bar');
129: 
130:     // Dynamic Password Strength Meter
131:     pwdInput.addEventListener('input', () => {
132:       const val = pwdInput.value;
133:       let score = 0;
134:       if (val.length >= 8) score += 33;
135:       if (/[A-Z]/.test(val) && /[0-9]/.test(val)) score += 34;
136:       if (/[^A-Za-z0-9]/.test(val)) score += 33;
137: 
138:       strengthBar.style.width = `${score}%`;
139:       if (score < 40) strengthBar.style.backgroundColor = '#EF4444';
140:       else if (score < 70) strengthBar.style.backgroundColor = '#F59E0B';
141:       else strengthBar.style.backgroundColor = '#10B981';
142:     });
143: 
144:     // Form Validation & Registration
145:     document.getElementById('signup-form').addEventListener('submit', function(e) {
146:       e.preventDefault();
147:       let valid = true;
148: 
149:       const name = document.getElementById('signup-name');
150:       const email = document.getElementById('signup-email');
151:       const pwd = document.getElementById('signup-password');
152:       const confirmPwd = document.getElementById('signup-confirm-password');
153:       const terms = document.getElementById('terms-agree');
154:       const confirmError = document.getElementById('confirm-error-msg');
155:       const termsError = document.getElementById('terms-error-msg');
156: 
157:       if (!name.value.trim()) { name.parentElement.classList.add('error'); valid = false; }
158:       else { name.parentElement.classList.remove('error'); }
159: 
160:       const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
161:       if (!emailRegex.test(email.value.trim())) { email.parentElement.classList.add('error'); valid = false; }
162:       else { email.parentElement.classList.remove('error'); }
163: 
164:       if (pwd.value.length < 8) { pwd.closest('.form-group').classList.add('error'); valid = false; }
165:       else { pwd.closest('.form-group').classList.remove('error'); }
166: 
167:       if (pwd.value !== confirmPwd.value) {
168:         confirmError.style.display = 'block';
169:         confirmPwd.style.borderColor = '#EF4444';
170:         valid = false;
171:       } else {
172:         confirmError.style.display = 'none';
173:         confirmPwd.style.borderColor = '';
174:       }
175: 
176:       if (!terms.checked) {
177:         termsError.style.display = 'block';
178:         valid = false;
179:       } else {
180:         termsError.style.display = 'none';
181:       }
182: 
183:       if (valid) {
184:         localStorage.setItem('stride_user', JSON.stringify({
185:           name: name.value.trim(),
186:           email: email.value.trim(),
187:           role: 'Member'
188:         }));
189:         this.style.display = 'none';
190:         document.getElementById('signup-success-view').style.display = 'block';
191:         STRIDE_APP.showToast('Account successfully created! Welcome.', 'success');
192:       }
193:     });
194:   </script>
195: </body>
196: </html>

