args.Content:
/* ==========================================================================
   STRIDE MARKETPLACE — SHARED DESIGN SYSTEM & LAYOUT
   Used across: sell.html, login.html, signup.html
   ========================================================================== */

:root {
  --bg-page: #0B0D12;
  --bg-surface: #11131A;
  --bg-card: #141720;
  --bg-elevated: #1B1F2B;
  --border-subtle: #292D38;
  --border-strong: #3B4152;

  --text-primary: #FFFFFF;
  --text-secondary: #A0A4AE;
  --text-muted: #767C8B;

  --neon-orange: #FF5A1F;
  --neon-orange-hover: #FF7340;
  --neon-orange-soft: rgba(255, 90, 31, 0.14);
  --accent-red: #EF4444;
  --accent-amber: #F59E0B;
  --accent-green: #10B981;

  --font-sans: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-display: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;

  --shadow-card: 0 20px 45px rgba(0, 0, 0, 0.45);
  --transition-fast: 0.18s ease;
  --transition-smooth: 0.28s ease;
}

/* Reset & Base */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--bg-page);
  background-image:
    radial-gradient(circle at 18% 0%, rgba(255, 90, 31, 0.08) 0%, transparent 40%),
    radial-gradient(circle at 85% 90%, rgba(255, 90, 31, 0.05) 0%, transparent 40%);
  color: var(--text-primary);
  font-family: var(--font-sans);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  background: none;
  border: none;
}

/* Accessibility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0.75rem;
  z-index: 2000;
  background: var(--neon-orange);
  color: #0B0D12;
  font-weight: 800;
  padding: 0.65rem 1rem;
  border-radius: var(--radius-sm);
}

.skip-link:focus {
  left: 0.75rem;
}

:focus-visible {
  outline: 2px solid var(--neon-orange);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

main {
  flex: 1 0 auto;
}

.text-neon {
  color: var(--neon-orange);
}

/* Announcement Bar (matches prototype top strip) */
.announcement-bar {
  background: linear-gradient(90deg, #12151F 0%, #1B1F2E 50%, #12151F 100%);
  border-bottom: 1px solid var(--border-subtle);
  padding: 0.5rem 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.5rem 1.5rem;
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  text-transform: uppercase;
}

.announcement-bar strong {
  color: var(--text-primary);
}

.announcement-divider {
  color: var(--neon-orange);
}

/* Header & Navigation */
.stride-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(11, 13, 18, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
}

.nav-inner {
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.brand-logo {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.4rem;
}

.nav-link {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 0.35rem 0;
  position: relative;
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: var(--neon-orange);
  border-radius: 99px;
}

.badge-hot {
  display: inline-block;
  margin-left: 0.3rem;
  padding: 0.1rem 0.38rem;
  border-radius: 99px;
  background: var(--neon-orange);
  color: #0B0D12;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  vertical-align: middle;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  cursor: pointer;
  transition: border-color var(--transition-fast), color var(--transition-fast), background var(--transition-fast);
}

.icon-btn:hover {
  border-color: var(--neon-orange);
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.icon-btn.active {
  border-color: var(--neon-orange);
  color: var(--neon-orange);
}

.user-pill {
  display: none;
  align-items: center;
  gap: 0.45rem;
  padding: 0.35rem 0.7rem;
  border-radius: 99px;
  background: var(--neon-orange-soft);
  border: 1px solid rgba(255, 90, 31, 0.45);
  font-size: 0.76rem;
  font-family: var(--font-mono);
  color: var(--text-primary);
}

.user-pill.visible {
  display: inline-flex;
}

.user-pill button {
  color: var(--neon-orange);
  font-weight: 700;
  cursor: pointer;
  margin-left: 0.25rem;
}

.mobile-menu-toggle {
  display: none;
}

/* Mobile Top Tab (matches prototype mobile "Home Tab") */
.mobile-home-strip {
  display: none;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  padding: 0.45rem 1rem;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--text-secondary);
}

/* Mobile Slide-Out Drawer */
.mobile-nav-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 900;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-smooth);
}

.mobile-nav-overlay.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: 0;
  width: min(320px, 86vw);
  height: 100vh;
  background: var(--bg-card);
  border-left: 1px solid var(--border-subtle);
  z-index: 950;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transform: translateX(100%);
  transition: transform var(--transition-smooth);
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--border-subtle);
}

.mobile-nav-close {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  cursor: pointer;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.mobile-nav-link {
  padding: 0.7rem 0.85rem;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-weight: 600;
  transition: background var(--transition-fast), color var(--transition-fast);
}

.mobile-nav-link:hover,
.mobile-nav-link.active {
  background: var(--bg-elevated);
  color: var(--neon-orange);
}

/* Shared Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 0.88rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.72rem 1.25rem;
  cursor: pointer;
  transition: transform var(--transition-fast), background var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.btn:active {
  transform: translateY(1px);
}

.btn-sm {
  padding: 0.48rem 0.9rem;
  font-size: 0.78rem;
}

.btn-lg {
  padding: 0.95rem 1.5rem;
  font-size: 0.95rem;
}

.btn-block {
  width: 100%;
}

.btn-primary {
  background: var(--neon-orange);
  color: #0B0D12;
  border: 1px solid var(--neon-orange);
}

.btn-primary:hover {
  background: var(--neon-orange-hover);
  box-shadow: 0 8px 24px rgba(255, 90, 31, 0.32);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
}

.btn-secondary:hover {
  border-color: var(--neon-orange);
  color: var(--neon-orange);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
}

.btn-outline:hover {
  border-color: var(--neon-orange);
  color: var(--neon-orange);
}

/* Shared Form Controls */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-label {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 0.82rem 1rem;
  color: var(--text-primary);
  font-size: 0.94rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input::placeholder {
  color: var(--text-muted);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--neon-orange);
  box-shadow: 0 0 0 3px rgba(255, 90, 31, 0.18);
}

.form-error-msg {
  display: none;
  color: var(--accent-red);
  font-size: 0.76rem;
  font-family: var(--font-mono);
}

.form-group.error .form-input,
.form-group.error .form-select,
.form-group.error .form-textarea {
  border-color: var(--accent-red);
}

.form-group.error .form-error-msg {
  display: block;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.85rem;
  border-radius: 99px;
  border: 1px solid rgba(255, 90, 31, 0.45);
  background: var(--neon-orange-soft);
  color: var(--neon-orange);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Footer (matches prototype: //STRIDE | Market service company | Tokyo • London • Paris) */
.stride-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  padding: 1.5rem 0;
  margin-top: auto;
}

.footer-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.footer-brand-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.footer-locations {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.85rem;
}

.location-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.82rem;
  font-family: var(--font-mono);
  color: var(--text-secondary);
  padding: 0.25rem 0.55rem;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: color var(--transition-fast), border-color var(--transition-fast);
}

.location-btn:hover,
.location-btn.active {
  color: var(--neon-orange);
  border-color: rgba(255, 90, 31, 0.4);
  background: var(--neon-orange-soft);
}

/* Toast Notifications */
.toast-container {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 1500;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  max-width: min(360px, calc(100vw - 2.5rem));
}

.stride-toast {
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-left: 4px solid var(--neon-orange);
  border-radius: var(--radius-md);
  padding: 0.85rem 1rem;
  box-shadow: var(--shadow-card);
  font-size: 0.86rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  animation: toastSlideIn 0.2s ease;
}

.stride-toast.success {
  border-left-color: var(--accent-green);
}

.stride-toast.error {
  border-left-color: var(--accent-red);
}

@keyframes toastSlideIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Modal Dialog (Terms / Forgot Password) */
.stride-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  z-index: 1200;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.stride-modal-backdrop.open {
  display: flex;
}

.stride-modal {
  width: 100%;
  max-width: 480px;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-card);
}

.stride-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border-subtle);
}

/* Responsive Breakpoints */
@media (max-width: 900px) {
  .nav-links {
    display: none;
  }

  .mobile-menu-toggle {
    display: inline-flex;
  }
}

@media (max-width: 640px) {
  .announcement-bar {
    display: none;
  }

  .mobile-home-strip {
    display: flex;
  }

  .nav-actions .btn {
    display: none;
  }

  .footer-bar {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* ==========================================================================
