    }
    if (controlEl) {
      controlEl.setAttribute('aria-invalid', hasError ? 'true' : 'false');
    }
  }

  /**
   * Wires a show/hide password toggle button to a password input.
   * @param {HTMLButtonElement|null} btn
   * @param {HTMLInputElement|null} input
   */
  function bindPasswordToggle(btn, input) {
    if (!btn || !input) return;
    btn.addEventListener('click', () => {
      const reveal = input.type === 'password';
      input.type = reveal ? 'text' : 'password';
      btn.setAttribute('aria-pressed', reveal ? 'true' : 'false');
      btn.setAttribute('aria-label', reveal ? 'Hide password' : 'Show password');
    });
  }

  /**
   * Opens an accessible modal dialog.
   * @param {HTMLElement|null} modalEl
   * @param {HTMLElement|null} [focusTarget]
   */
  function openModal(modalEl, focusTarget) {
    if (!modalEl) return;
    modalEl.classList.add('open');
    modalEl.setAttribute('aria-hidden', 'false');
    if (focusTarget) focusTarget.focus();
  }

  /**
   * Closes an accessible modal dialog.
   * @param {HTMLElement|null} modalEl
   */
  function closeModal(modalEl) {
    if (!modalEl) return;
    modalEl.classList.remove('open');
    modalEl.setAttribute('aria-hidden', 'true');
  }

  function getCurrentUser() {
    const raw = localStorage.getItem(USER_STORAGE_KEY) || sessionStorage.getItem(USER_STORAGE_KEY);
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return null;
    }
  }

  function setCurrentUser(user, keepLoggedIn) {
    const payload = JSON.stringify(user);
    localStorage.removeItem(USER_STORAGE_KEY);
    sessionStorage.removeItem(USER_STORAGE_KEY);
    if (keepLoggedIn) {
      localStorage.setItem(USER_STORAGE_KEY, payload);
    } else {
      sessionStorage.setItem(USER_STORAGE_KEY, payload);
    }
    syncHeaderUserState();
  }

  function clearCurrentUser() {
    localStorage.removeItem(USER_STORAGE_KEY);
    sessionStorage.removeItem(USER_STORAGE_KEY);
    syncHeaderUserState();
  }

  function syncHeaderUserState() {
    const pill = document.getElementById('header-user-pill');
    const nameEl = document.getElementById('header-user-name');
    if (!pill || !nameEl) return;

    const user = getCurrentUser();
    if (user && user.name) {
      nameEl.textContent = user.name;
      pill.classList.add('visible');
    } else {
      nameEl.textContent = '';
      pill.classList.remove('visible');
    }
  }

  function getActiveHub() {
    return localStorage.getItem(HUB_STORAGE_KEY) || 'Tokyo';
  }

  function initMobileDrawer() {
    const toggleBtn = document.getElementById('mobile-menu-toggle');
    const closeBtn = document.getElementById('mobile-nav-close');
    const drawer = document.getElementById('mobile-nav-drawer');
    const overlay = document.getElementById('mobile-nav-overlay');
    if (!toggleBtn || !drawer || !overlay) return;

    function setDrawerOpen(open) {
      drawer.classList.toggle('open', open);
      overlay.classList.toggle('open', open);
      drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
      toggleBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (open && closeBtn) closeBtn.focus();
    }

    toggleBtn.addEventListener('click', () => setDrawerOpen(true));
    if (closeBtn) closeBtn.addEventListener('click', () => setDrawerOpen(false));
    overlay.addEventListener('click', () => setDrawerOpen(false));

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && drawer.classList.contains('open')) {
        setDrawerOpen(false);
        toggleBtn.focus();
      }
    });
  }

  function initFooterHubs() {
    const hubButtons = document.querySelectorAll('.location-btn[data-hub]');
    if (!hubButtons.length) return;

    const savedHub = getActiveHub();
    hubButtons.forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.hub === savedHub);
      btn.addEventListener('click', () => {
        const hub = btn.dataset.hub;
        localStorage.setItem(HUB_STORAGE_KEY, hub);
        hubButtons.forEach((b) => b.classList.toggle('active', b === btn));
        showToast(`Authentication hub set to ${hub}`, 'info');
      });
    });
  }

  function initHeaderSignout() {
    const signoutBtn = document.getElementById('header-signout-btn');
    if (!signoutBtn) return;
    signoutBtn.addEventListener('click', () => {
      clearCurrentUser();
      showToast('Signed out of STRIDE.', 'info');
      window.dispatchEvent(new CustomEvent('stride:authchange'));
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    syncHeaderUserState();
    initMobileDrawer();
    initFooterHubs();
    initHeaderSignout();
  });

  window.STRIDE_APP = {
    formatPrice,
    showToast,
    setFieldError,
    bindPasswordToggle,
    openModal,
    closeModal,
    getCurrentUser,
    setCurrentUser,
    clearCurrentUser,
    getActiveHub
  };
})();

/* ==========================================================================
   SELL / CONSIGNMENT PAGE LOGIC (sell.html)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('sell-form');
  if (!form) return;

  const MIN_PRICE = 50;
  const FEE_RATE = 0.095;
  const LAB_FEE = 5;
  const MIN_PHOTOS = 2;
  const MAX_FILE_BYTES = 10 * 1024 * 1024;
  const ALLOWED_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/svg+xml'];

  const brandEl = document.getElementById('sell-brand');
  const modelEl = document.getElementById('sell-model');
  const sizeEl = document.getElementById('sell-size');
  const conditionEl = document.getElementById('sell-condition');
  const skuEl = document.getElementById('sell-sku');
  const priceEl = document.getElementById('sell-price');

  const grossEl = document.getElementById('payout-gross');
  const feeEl = document.getElementById('payout-fee');
  const processingEl = document.getElementById('payout-processing');
  const netEl = document.getElementById('payout-net');

  const dropzone = document.getElementById('upload-dropzone');
  const fileInput = document.getElementById('sneaker-file-input');
  const loadSamplesBtn = document.getElementById('load-sample-photos-btn');
  const previewGrid = document.getElementById('upload-preview-grid');
  const photoCounterEl = document.getElementById('photo-counter');
  const photoGroup = document.getElementById('group-photos');

  const confirmationView = document.getElementById('sell-confirmation-view');
  const confirmedRefEl = document.getElementById('confirmed-ref-code');
  const confirmedSummaryEl = document.getElementById('confirmed-summary-details');
  const submitAnotherBtn = document.getElementById('submit-another-btn');

  let uploadedPhotos = [];

  /** Computes gross, 9.5% STRIDE fee, $5 lab fee, and net seller payout. */
  function getPayoutBreakdown(rawValue) {
    const gross = parseFloat(rawValue) || 0;
    if (gross <= 0) {
      return { gross: 0, fee: 0, processing: 0, net: 0 };
    }
    const fee = Math.round(gross * FEE_RATE);
    const net = Math.max(0, gross - fee - LAB_FEE);
    return { gross, fee, processing: LAB_FEE, net };
  }

  function updatePayoutDisplay() {
    const { gross, fee, processing, net } = getPayoutBreakdown(priceEl.value);
    grossEl.textContent = STRIDE_APP.formatPrice(gross);
    feeEl.textContent = `-${STRIDE_APP.formatPrice(fee)}`;
    processingEl.textContent = `-${STRIDE_APP.formatPrice(processing)}`;
    netEl.textContent = `${STRIDE_APP.formatPrice(net)} USD`;
  }

  function renderPhotoPreviews() {
    previewGrid.innerHTML = '';

    uploadedPhotos.forEach((photo, index) => {
      const item = document.createElement('div');
      item.className = 'upload-preview-item';

      const img = document.createElement('img');
      img.src = photo.src;
      img.alt = `Sneaker preview ${index + 1}: ${photo.name}`;

      const label = document.createElement('span');
      label.className = 'preview-label';
      label.textContent = `Preview ${index + 1}`;

      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'preview-remove-btn';
      removeBtn.setAttribute('aria-label', `Remove photo ${index + 1}`);
      removeBtn.textContent = '✕';
      removeBtn.addEventListener('click', () => {
        uploadedPhotos.splice(index, 1);
        renderPhotoPreviews();
      });

      item.appendChild(img);
      item.appendChild(label);
      item.appendChild(removeBtn);
      previewGrid.appendChild(item);
    });

    const count = uploadedPhotos.length;
    const ready = count >= MIN_PHOTOS;
    photoCounterEl.textContent = ready
      ? `${count} photos ready`
      : `${count} / ${MIN_PHOTOS} minimum`;
    photoCounterEl.classList.toggle('ready', ready);

    if (ready) {
      STRIDE_APP.setFieldError(photoGroup, dropzone, false);
    }
  }

  function handleIncomingFiles(fileList) {
    const files = Array.from(fileList || []);
    files.forEach((file) => {
      if (!ALLOWED_TYPES.includes(file.type)) {
        STRIDE_APP.showToast(`Unsupported format: ${file.name}`, 'error');
        return;
      }
      if (file.size > MAX_FILE_BYTES) {
        STRIDE_APP.showToast(`${file.name} exceeds 10MB limit.`, 'error');
        return;
      }
      const reader = new FileReader();
      reader.onload = (event) => {
        uploadedPhotos.push({ name: file.name, src: event.target.result });
        renderPhotoPreviews();
      };
      reader.readAsDataURL(file);
    });
  }

  priceEl.addEventListener('input', updatePayoutDisplay);

  dropzone.addEventListener('click', () => fileInput.click());
  dropzone.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      fileInput.click();
    }
  });

  fileInput.addEventListener('change', (e) => {
    handleIncomingFiles(e.target.files);
    fileInput.value = '';
  });

  dropzone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropzone.classList.add('dragover');
  });

  dropzone.addEventListener('dragleave', () => {
    dropzone.classList.remove('dragover');
  });

  dropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropzone.classList.remove('dragover');
    if (e.dataTransfer && e.dataTransfer.files) {
      handleIncomingFiles(e.dataTransfer.files);
    }
  });

  if (loadSamplesBtn) {
    loadSamplesBtn.addEventListener('click', () => {
      uploadedPhotos = [
        { name: 'Lateral Profile', src: '../images/sneaker-sample-1.svg' },
        { name: 'Medial Profile', src: '../images/sneaker-sample-2.svg' }
      ];
      renderPhotoPreviews();
      STRIDE_APP.showToast('2 sample sneaker photos loaded.', 'info');
    });
  }

  function validateForm() {
    let valid = true;

    const brandMissing = !brandEl.value;
    STRIDE_APP.setFieldError(document.getElementById('group-brand'), brandEl, brandMissing);
    if (brandMissing) valid = false;

    const modelMissing = modelEl.value.trim().length < 2;
    STRIDE_APP.setFieldError(document.getElementById('group-model'), modelEl, modelMissing);
    if (modelMissing) valid = false;

    const sizeMissing = !sizeEl.value;
    STRIDE_APP.setFieldError(document.getElementById('group-size'), sizeEl, sizeMissing);
    if (sizeMissing) valid = false;

    const parsedPrice = parseFloat(priceEl.value);
    const priceInvalid = Number.isNaN(parsedPrice) || parsedPrice < MIN_PRICE;
    STRIDE_APP.setFieldError(document.getElementById('group-price'), priceEl, priceInvalid);
    if (priceInvalid) valid = false;

    const photosMissing = uploadedPhotos.length < MIN_PHOTOS;
    STRIDE_APP.setFieldError(photoGroup, dropzone, photosMissing);
    if (photosMissing) valid = false;

    return valid;
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    if (!validateForm()) {
      STRIDE_APP.showToast('Please fix the highlighted fields before submitting.', 'error');
      return;
    }

    const boxChecked = form.querySelector('input[name="originalBox"]:checked');
    const originalBox = boxChecked ? boxChecked.value : 'Yes';
    const refCode = `#CSG-${Math.floor(100000 + Math.random() * 900000)}`;
    const payout = getPayoutBreakdown(priceEl.value);
    const hub = STRIDE_APP.getActiveHub();

    const submission = {
      refCode,
      brand: brandEl.value,
      model: modelEl.value.trim(),
      size: sizeEl.value,
      condition: conditionEl.value,
      originalBox,
      sku: skuEl.value.trim() || 'N/A',
      askingPrice: payout.gross,
      netPayout: payout.net,
      photoCount: uploadedPhotos.length,
      hub,
      submittedAt: new Date().toISOString()
    };

    const existing = JSON.parse(localStorage.getItem('stride_consignments') || '[]');
    existing.unshift(submission);
    localStorage.setItem('stride_consignments', JSON.stringify(existing));

    confirmedRefEl.textContent = refCode;
    confirmedSummaryEl.innerHTML = '';
    const summaryTitle = document.createElement('strong');
    summaryTitle.style.color = 'var(--text-primary)';
    summaryTitle.textContent = `${submission.brand} — ${submission.model} (${submission.size})`;
    const summaryMeta = document.createElement('p');
    summaryMeta.style.marginTop = '0.35rem';
    summaryMeta.textContent =
      `Condition: ${submission.condition} • Original Box: ${submission.originalBox} • ` +
      `Est. Net Payout: ${STRIDE_APP.formatPrice(submission.netPayout)} USD • Hub: ${submission.hub}`;
    confirmedSummaryEl.appendChild(summaryTitle);
    confirmedSummaryEl.appendChild(summaryMeta);

    form.style.display = 'none';
    confirmationView.classList.add('visible');
    STRIDE_APP.showToast(`Consignment ${refCode} submitted!`, 'success');
  });

  if (submitAnotherBtn) {
    submitAnotherBtn.addEventListener('click', () => {
      form.reset();
      uploadedPhotos = [];
      renderPhotoPreviews();
      updatePayoutDisplay();
      confirmationView.classList.remove('visible');
      form.style.display = 'block';
      brandEl.focus();
    });
  }

  updatePayoutDisplay();
  renderPhotoPreviews();
});

/* ==========================================================================
   LOGIN PAGE LOGIC (login.html)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('login-form');
  if (!form) return;

  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const emailEl = document.getElementById('login-email');
  const passwordEl = document.getElementById('login-password');
  const keepLoggedInEl = document.getElementById('keep-logged-in');
  const togglePwdBtn = document.getElementById('toggle-login-password');
  const demoBtn = document.getElementById('demo-fill-btn');

  const emailGroup = document.getElementById('group-login-email');
  const passwordGroup = document.getElementById('group-login-password');

  const successView = document.getElementById('login-success-view');
  const vaultMetaEl = document.getElementById('vault-user-meta');
  const vaultSignoutBtn = document.getElementById('vault-signout-btn');

  const forgotBtn = document.getElementById('forgot-password-btn');
  const forgotModal = document.getElementById('forgot-modal');
  const closeForgotBtn = document.getElementById('close-forgot-modal');
  const forgotForm = document.getElementById('forgot-form');
  const forgotEmailEl = document.getElementById('forgot-email');
  const forgotEmailGroup = document.getElementById('group-forgot-email');

  STRIDE_APP.bindPasswordToggle(togglePwdBtn, passwordEl);

  function renderAuthState() {
    const activeUser = STRIDE_APP.getCurrentUser();
    if (activeUser && activeUser.email) {
      form.style.display = 'none';
      successView.classList.add('visible');
      vaultMetaEl.innerHTML = '';

      const row1 = document.createElement('div');
      row1.innerHTML = '<strong>Collector:</strong> ';
      row1.appendChild(document.createTextNode(activeUser.name || 'STRIDE Member'));

      const row2 = document.createElement('div');
      row2.innerHTML = '<strong>Email:</strong> ';
      row2.appendChild(document.createTextNode(activeUser.email));

      const row3 = document.createElement('div');
      row3.innerHTML = '<strong>Status:</strong> ';
      row3.appendChild(document.createTextNode(activeUser.role || 'Verified Collector'));

      vaultMetaEl.appendChild(row1);
      vaultMetaEl.appendChild(row2);
      vaultMetaEl.appendChild(row3);
    } else {
      successView.classList.remove('visible');
      form.style.display = 'flex';
    }
  }

  if (demoBtn) {
    demoBtn.addEventListener('click', () => {
      emailEl.value = 'i263195@isb.nu.edu.pk';
      passwordEl.value = 'Stride2026!';
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
      STRIDE_APP.showToast('Demo credentials populated. Click Sign In to enter.', 'info');
    });
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const emailVal = emailEl.value.trim();
    const pwdVal = passwordEl.value;

    const emailInvalid = !EMAIL_REGEX.test(emailVal);
    const pwdInvalid = pwdVal.length < 6;

    STRIDE_APP.setFieldError(emailGroup, emailEl, emailInvalid);
    STRIDE_APP.setFieldError(passwordGroup, passwordEl, pwdInvalid);

    if (emailInvalid || pwdInvalid) {
      STRIDE_APP.showToast('Please check your email and password.', 'error');
      return;
    }

    const accounts = JSON.parse(localStorage.getItem('stride_accounts') || '[]');
    const matched = accounts.find((acc) => acc.email.toLowerCase() === emailVal.toLowerCase());
    const userName = matched
      ? matched.name
      : emailVal === 'i263195@isb.nu.edu.pk'
        ? 'Danyal Mehdi'
        : emailVal.split('@')[0];

    STRIDE_APP.setCurrentUser(
      {
        name: userName,
        email: emailVal,
        role: 'Verified Collector'
      },
      Boolean(keepLoggedInEl && keepLoggedInEl.checked)
    );

    STRIDE_APP.showToast(`Welcome back, ${userName}! Vault unlocked.`, 'success');
    renderAuthState();
  });

  if (vaultSignoutBtn) {
    vaultSignoutBtn.addEventListener('click', () => {
      STRIDE_APP.clearCurrentUser();
      form.reset();
      renderAuthState();
      STRIDE_APP.showToast('Signed out of your vault.', 'info');
    });
  }

  if (forgotBtn && forgotModal) {
    forgotBtn.addEventListener('click', () => {
      forgotEmailEl.value = emailEl.value.trim();
      STRIDE_APP.setFieldError(forgotEmailGroup, forgotEmailEl, false);
      STRIDE_APP.openModal(forgotModal, forgotEmailEl);
    });
  }

  if (closeForgotBtn && forgotModal) {
    closeForgotBtn.addEventListener('click', () => STRIDE_APP.closeModal(forgotModal));
    forgotModal.addEventListener('click', (e) => {
      if (e.target === forgotModal) STRIDE_APP.closeModal(forgotModal);
    });
  }

  if (forgotForm) {
    forgotForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const targetEmail = forgotEmailEl.value.trim();
      const invalid = !EMAIL_REGEX.test(targetEmail);
      STRIDE_APP.setFieldError(forgotEmailGroup, forgotEmailEl, invalid);
      if (invalid) return;

      STRIDE_APP.closeModal(forgotModal);
      STRIDE_APP.showToast(`Password reset instructions prepared for ${targetEmail}.`, 'success');
    });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && forgotModal && forgotModal.classList.contains('open')) {
      STRIDE_APP.closeModal(forgotModal);
    }
  });

  window.addEventListener('stride:authchange', renderAuthState);
  renderAuthState();
});

/* ==========================================================================
   SIGN UP PAGE LOGIC (signup.html)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('signup-form');
  if (!form) return;

  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const nameEl = document.getElementById('signup-name');
  const emailEl = document.getElementById('signup-email');
  const passwordEl = document.getElementById('signup-password');
  const confirmEl = document.getElementById('signup-confirm-password');
  const termsEl = document.getElementById('terms-agree');

  const nameGroup = document.getElementById('group-signup-name');
  const emailGroup = document.getElementById('group-signup-email');
  const passwordGroup = document.getElementById('group-signup-password');
  const confirmGroup = document.getElementById('group-signup-confirm');
  const termsGroup = document.getElementById('group-terms');

  const strengthBar = document.getElementById('strength-bar');
  const ruleEls = {
    length: document.getElementById('rule-length'),
    upper: document.getElementById('rule-upper'),
    number: document.getElementById('rule-number'),
    symbol: document.getElementById('rule-symbol')
  };

  const successView = document.getElementById('signup-success-view');
  const welcomeMsgEl = document.getElementById('signup-welcome-msg');

  const termsModal = document.getElementById('terms-modal');
  const openTermsBtn = document.getElementById('open-terms-btn');
  const closeTermsBtn = document.getElementById('close-terms-modal');
  const acceptTermsBtn = document.getElementById('accept-terms-modal-btn');

  STRIDE_APP.bindPasswordToggle(document.getElementById('toggle-signup-password'), passwordEl);
  STRIDE_APP.bindPasswordToggle(document.getElementById('toggle-confirm-password'), confirmEl);

  function evaluatePassword(value) {
    return {
      length: value.length >= 8,
      upper: /[A-Z]/.test(value),
      number: /[0-9]/.test(value),
      symbol: /[^A-Za-z0-9]/.test(value)
    };
  }

  function updatePasswordStrength() {
    const checks = evaluatePassword(passwordEl.value);
    let metCount = 0;

    Object.keys(checks).forEach((key) => {
      const isMet = checks[key];
      if (isMet) metCount += 1;
      if (ruleEls[key]) {
        ruleEls[key].classList.toggle('met', isMet);
      }
    });

    const pct = (metCount / 4) * 100;
    strengthBar.style.width = `${pct}%`;
    if (metCount <= 1) {
      strengthBar.style.backgroundColor = 'var(--accent-red)';
    } else if (metCount <= 3) {
      strengthBar.style.backgroundColor = 'var(--accent-amber)';
    } else {
      strengthBar.style.backgroundColor = 'var(--accent-green)';
    }

    return metCount === 4;
  }

  function checkPasswordMatch() {
    if (!confirmEl.value) return false;
    const mismatch = passwordEl.value !== confirmEl.value;
    STRIDE_APP.setFieldError(confirmGroup, confirmEl, mismatch);
    return !mismatch;
  }

  passwordEl.addEventListener('input', () => {
    const allMet = updatePasswordStrength();
    if (allMet) {
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
    }
    if (confirmEl.value) {
      checkPasswordMatch();
    }
  });

  confirmEl.addEventListener('input', checkPasswordMatch);

  termsEl.addEventListener('change', () => {
    if (termsEl.checked) {
      STRIDE_APP.setFieldError(termsGroup, termsEl, false);
    }
  });

  if (openTermsBtn && termsModal) {
    openTermsBtn.addEventListener('click', () => STRIDE_APP.openModal(termsModal, closeTermsBtn));
  }

  if (closeTermsBtn && termsModal) {
    closeTermsBtn.addEventListener('click', () => STRIDE_APP.closeModal(termsModal));
    termsModal.addEventListener('click', (e) => {
      if (e.target === termsModal) STRIDE_APP.closeModal(termsModal);
    });
  }

  if (acceptTermsBtn && termsModal) {
    acceptTermsBtn.addEventListener('click', () => {
      termsEl.checked = true;
      STRIDE_APP.setFieldError(termsGroup, termsEl, false);
      STRIDE_APP.closeModal(termsModal);
    });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && termsModal && termsModal.classList.contains('open')) {
      STRIDE_APP.closeModal(termsModal);
    }
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let valid = true;

    const fullName = nameEl.value.trim();
    const emailVal = emailEl.value.trim();

    const nameInvalid = fullName.length < 2;
    STRIDE_APP.setFieldError(nameGroup, nameEl, nameInvalid);
    if (nameInvalid) valid = false;

    const emailInvalid = !EMAIL_REGEX.test(emailVal);
    STRIDE_APP.setFieldError(emailGroup, emailEl, emailInvalid);
    if (emailInvalid) valid = false;

    const passwordStrong = updatePasswordStrength();
    STRIDE_APP.setFieldError(passwordGroup, passwordEl, !passwordStrong);
    if (!passwordStrong) valid = false;

    const confirmInvalid = !confirmEl.value || passwordEl.value !== confirmEl.value;
    STRIDE_APP.setFieldError(confirmGroup, confirmEl, confirmInvalid);
    if (confirmInvalid) valid = false;

    const termsInvalid = !termsEl.checked;
    STRIDE_APP.setFieldError(termsGroup, termsEl, termsInvalid);
    if (termsInvalid) valid = false;

    if (!valid) {
      STRIDE_APP.showToast('Please complete all required registration fields.', 'error');
      return;
    }

    const accounts = JSON.parse(localStorage.getItem('stride_accounts') || '[]');
    const filtered = accounts.filter((a) => a.email.toLowerCase() !== emailVal.toLowerCase());
    filtered.push({
      name: fullName,
      email: emailVal,
      createdAt: new Date().toISOString()
    });
    localStorage.setItem('stride_accounts', JSON.stringify(filtered));

    STRIDE_APP.setCurrentUser(
      {
        name: fullName,
        email: emailVal,
        role: 'Verified Member'
      },
      true
    );

    form.style.display = 'none';
