/**
 * Safely parses JSON from localStorage with a fallback value.
 * @template T
 * @param {string} key
 * @param {T} fallback
 * @returns {T}
 */
function readJsonStorage(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

/**
 * Opens an accessible modal dialog and remembers where to restore focus on close.
 * @param {HTMLElement|null} modalEl
 * @param {HTMLElement|null} [focusTarget]
 * @param {HTMLElement|null} [returnFocusEl]
 */
function openModal(modalEl, focusTarget, returnFocusEl) {
  if (!modalEl) return;
  const opener = returnFocusEl || document.activeElement;
  if (opener instanceof HTMLElement) {
    modalReturnFocus.set(modalEl, opener);
  }
  modalEl.classList.add('open');
  modalEl.setAttribute('aria-hidden', 'false');
  if (focusTarget) focusTarget.focus();
}

/**
 * Closes an accessible modal dialog and restores focus to its opener.
 * @param {HTMLElement|null} modalEl
 */
function closeModal(modalEl) {
  if (!modalEl) return;
  modalEl.classList.remove('open');
  modalEl.setAttribute('aria-hidden', 'true');
  const opener = modalReturnFocus.get(modalEl);
  if (opener && typeof opener.focus === 'function') {
    opener.focus();
  }
}

