$port = 9229
$tmpProfile = Join-Path $env:TEMP "stride_cdp_$PID"
New-Item -ItemType Directory -Force -Path $tmpProfile | Out-Null

$proc = Start-Process -FilePath $edge -ArgumentList @(
  '--headless=new',
  '--disable-gpu',
  "--remote-debugging-port=$port",
  "--user-data-dir=$tmpProfile",
  'about:blank'
) -PassThru

try {
  $targets = $null
  for ($i = 0; $i -lt 30; $i++) {
    Start-Sleep -Milliseconds 250
    try {
      $targets = Invoke-RestMethod "http://127.0.0.1:$port/json/list"
      if ($targets.Count -gt 0) { break }
    } catch {}
  }
  $pageTarget = $targets | Where-Object { $_.type -eq 'page' } | Select-Object -First 1
  if (-not $pageTarget) { throw "No CDP page target found" }

  $ws = [System.Net.WebSockets.ClientWebSocket]::new()
  $ct = [System.Threading.CancellationToken]::None
  $ws.ConnectAsync([Uri]$pageTarget.webSocketDebuggerUrl, $ct).GetAwaiter().GetResult()

  $script:msgId = 0
  function Invoke-Cdp($method, $params = @{}) {
    $script:msgId++
    $id = $script:msgId
    $json = (@{ id = $id; method = $method; params = $params } | ConvertTo-Json -Depth 10 -Compress)
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
    $seg = [ArraySegment[byte]]::new($bytes)
    $ws.SendAsync($seg, [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $ct).GetAwaiter().GetResult()

    $buf = New-Object byte[] 65536
    while ($true) {
      $ms = New-Object System.IO.MemoryStream
      do {
        $rseg = [ArraySegment[byte]]::new($buf)
        $res = $ws.ReceiveAsync($rseg, $ct).GetAwaiter().GetResult()
        $ms.Write($buf, 0, $res.Count)
      } while (-not $res.EndOfMessage)
      $txt = [System.Text.Encoding]::UTF8.GetString($ms.ToArray())
      $obj = $txt | ConvertFrom-Json
      if ($obj.id -eq $id) { return $obj }
    }
  }

  function Eval-Js($expr) {
    $r = Invoke-Cdp 'Runtime.evaluate' @{ expression = $expr; returnByValue = $true; awaitPromise = $true }
    if ($r.result.exceptionDetails) { throw "JS Exception: $($r.result.exceptionDetails.text)" }
    return $r.result.result.value
  }

  function Nav-To($relPath) {
    $uri = ([System.Uri](Join-Path $root $relPath)).AbsoluteUri
    Invoke-Cdp 'Page.navigate' @{ url = $uri } | Out-Null
    Start-Sleep -Milliseconds 500
  }

  Invoke-Cdp 'Page.enable' | Out-Null
  Invoke-Cdp 'Runtime.enable' | Out-Null

  # Responsive check across all 3 pages (Desktop 1280x800 and Mobile 375x812)
  foreach ($rel in @('html\sell.html', 'html\login.html', 'html\signup.html')) {
    Nav-To $rel
    Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{ width = 1280; height = 800; deviceScaleFactor = 1; mobile = $false } | Out-Null
    Start-Sleep -Milliseconds 150
    $desk = Eval-Js "({ sw: document.documentElement.scrollWidth, iw: window.innerWidth })"
    Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{ width = 375; height = 812; deviceScaleFactor = 2; mobile = $true } | Out-Null
    Start-Sleep -Milliseconds 150
    $mob = Eval-Js "({ sw: document.documentElement.scrollWidth, iw: window.innerWidth })"
    Write-Output "RESPONSIVE $rel -> desktop=$($desk.sw)/$($desk.iw) mobile=$($mob.sw)/$($mob.iw)"
    if ($desk.sw -gt $desk.iw -or $mob.sw -gt $mob.iw) { throw "Horizontal overflow on $rel" }
  }

  Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{ width = 1280; height = 800; deviceScaleFactor = 1; mobile = $false } | Out-Null

  # Test sell.html
  Nav-To 'html\sell.html'
  $sellTest = Eval-Js @"
(() => {
  const price = document.getElementById('sell-price');
  price.value = '190';
  price.dispatchEvent(new Event('input', { bubbles: true }));
  const payout190 = {
    gross: document.getElementById('payout-gross').textContent,
    fee: document.getElementById('payout-fee').textContent,
    proc: document.getElementById('payout-processing').textContent,
    net: document.getElementById('payout-net').textContent
  };
  document.getElementById('sell-brand').value = 'Air Jordan';
  document.getElementById('sell-model').value = 'Air Jordan 4 Military Black';
  document.getElementById('sell-size').value = 'US 10';
  document.getElementById('load-sample-photos-btn').click();
  const photoCounter = document.getElementById('photo-counter').textContent;
  document.getElementById('sell-form').dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
  const confirmed = document.getElementById('sell-confirmation-view').classList.contains('visible');
  const refCode = document.getElementById('confirmed-ref-code').textContent.trim();
  return { payout190, photoCounter, confirmed, refCode };
})()
"@
  Write-Output ("SELL_TEST=" + ($sellTest | ConvertTo-Json -Compress))

  # Test login.html
  Nav-To 'html\login.html'
  $loginTest = Eval-Js @"
(() => {
  localStorage.clear(); sessionStorage.clear();
  location.reload();
  return 'ready';
})()
"@
  Start-Sleep -Milliseconds 350
  $loginTest = Eval-Js @"
(() => {
  document.getElementById('demo-fill-btn').click();
  const emailVal = document.getElementById('login-email').value;
  document.getElementById('login-form').dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
  const unlocked = document.getElementById('login-success-view').classList.contains('visible');
  document.getElementById('vault-signout-btn').click();
  const signedOut = !document.getElementById('login-success-view').classList.contains('visible');
  return { emailVal, unlocked, signedOut };
})()
"@
  Write-Output ("LOGIN_TEST=" + ($loginTest | ConvertTo-Json -Compress))

  # Test signup.html
  Nav-To 'html\signup.html'
  $signupTest = Eval-Js @"
(() => {
  document.getElementById('signup-name').value = 'Danyal Mehdi';
  document.getElementById('signup-email').value = 'i263195@isb.nu.edu.pk';
  const pwd = document.getElementById('signup-password');
  pwd.value = 'Stride2026!';
  pwd.dispatchEvent(new Event('input', { bubbles: true }));
  const rulesMet = ['rule-length','rule-upper','rule-number','rule-symbol'].every(id => document.getElementById(id).classList.contains('met'));
  const barWidth = document.getElementById('strength-bar').style.width;
  const conf = document.getElementById('signup-confirm-password');
  conf.value = 'Stride2026!';
  conf.dispatchEvent(new Event('input', { bubbles: true }));
  document.getElementById('terms-agree').checked = true;
  document.getElementById('signup-form').dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
  const created = document.getElementById('signup-success-view').classList.contains('visible');
  return { rulesMet, barWidth, created };
})()
"@
  Write-Output ("SIGNUP_TEST=" + ($signupTest | ConvertTo-Json -Compress))
  $ws.Dispose()
} finally {
  if ($proc -and -not $proc.HasExited) { Stop-Process -Id $proc.Id -Force }
  Start-Sleep -Milliseconds 200
  Remove-Item -Recurse -Force $tmpProfile -ErrorAction SilentlyContinue
}

args.Content:
/* ==========================================================================
   SIGN UP PAGE STYLES (signup.html + Bootstrap 5 Dark-Neon Theme Overrides)
   ========================================================================== */

.auth-wrapper {
  min-height: calc(100vh - 180px);
  display: flex;
  align-items: center;
  padding: 2.75rem 0;
}

.auth-card {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle) !important;
  border-radius: var(--radius-xl);
  padding: 2.4rem 2.2rem;
  box-shadow: var(--shadow-card);
  color: var(--text-primary);
  position: relative;
  overflow: hidden;
}

.auth-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--neon-orange), transparent);
}

.auth-header {
  text-align: center;
  margin-bottom: 1.75rem;
}

.auth-brand-mark {
  margin: 0 auto 1rem;
}

.auth-header h1 {
  font-size: clamp(1.45rem, 3vw, 1.85rem);
  font-weight: 900;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 0.4rem;
}

.auth-header p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 0;
}

.signup-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

/* Override Bootstrap .form-control / .form-check defaults for STRIDE dark theme */
.signup-form .form-label {
  margin-bottom: 0;
}

.signup-form .form-control.form-input {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-primary);
  border-radius: var(--radius-md);
  padding: 0.82rem 1rem;
}

.signup-form .form-control.form-input::placeholder {
  color: var(--text-muted);
}

.signup-form .form-control.form-input:focus {
  background-color: var(--bg-surface);
  color: var(--text-primary);
  border-color: var(--neon-orange);
  box-shadow: 0 0 0 3px rgba(255, 90, 31, 0.18);
}

.form-group.error .form-control.form-input {
  border-color: var(--accent-red);
}

.auth-password-wrap {
  position: relative;
}

.auth-password-wrap .form-control.form-input {
  padding-right: 3rem;
}

.password-toggle-btn {
  position: absolute;
  right: 0.65rem;
  top: 50%;
  transform: translateY(-50%);
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}

.password-toggle-btn:hover,
.password-toggle-btn[aria-pressed='true'] {
  color: var(--neon-orange);
  background: var(--neon-orange-soft);
}

/* Password Strength Bar & 4-Item Prototype Checklist */
.strength-meter {
  height: 5px;
  background: var(--border-subtle);
  border-radius: 99px;
  margin-top: 0.35rem;
  overflow: hidden;
}

.strength-bar {
  height: 100%;
  width: 0%;
  background: var(--accent-red);
  transition: width 0.25s ease, background-color 0.25s ease;
}

.password-checklist {
  margin-top: 0.45rem;
  margin-left: 0;
  margin-right: 0;
  padding: 0.65rem 0.75rem;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--text-muted);
}

.pwd-rule {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  transition: color var(--transition-fast);
}

.pwd-rule-box {
  width: 15px;
  height: 15px;
  border-radius: 4px;
  border: 1px solid var(--border-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.68rem;
  flex-shrink: 0;
}

.pwd-rule.met {
  color: var(--accent-green);
}

.pwd-rule.met .pwd-rule-box {
  background: rgba(16, 185, 129, 0.18);
  border-color: var(--accent-green);
  color: var(--accent-green);
}

/* Terms Checkbox */
.terms-check-wrap {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding-left: 0;
  margin-bottom: 0;
}

.terms-check-wrap .form-check-input {
  float: none;
  margin-left: 0;
  margin-top: 0.2rem;
  width: 1.05rem;
  height: 1.05rem;
  background-color: var(--bg-surface);
  border-color: var(--border-strong);
  cursor: pointer;
  flex-shrink: 0;
}

.terms-check-wrap .form-check-input:checked {
  background-color: var(--neon-orange);
  border-color: var(--neon-orange);
}

.terms-check-wrap .form-check-input:focus {
  box-shadow: 0 0 0 3px rgba(255, 90, 31, 0.2);
}

.terms-check-text {
  font-size: 0.84rem;
  color: var(--text-secondary);
  line-height: 1.45;
  cursor: pointer;
}

.terms-link-btn {
  color: var(--neon-orange);
  font-weight: 700;
  cursor: pointer;
  padding: 0;
}

.terms-link-btn:hover {
  text-decoration: underline;
}

/* Keep STRIDE primary/secondary button branding above Bootstrap defaults */
.auth-card .btn-primary,
.stride-bs-modal .btn-primary {
  background-color: var(--neon-orange);
  border-color: var(--neon-orange);
  color: #0B0D12;
  font-weight: 700;
}

.auth-card .btn-primary:hover,
.auth-card .btn-primary:focus,
.stride-bs-modal .btn-primary:hover {
  background-color: var(--neon-orange-hover);
  border-color: var(--neon-orange-hover);
  color: #0B0D12;
}

.auth-card .btn-secondary {
  background-color: var(--bg-elevated);
  border-color: var(--border-strong);
  color: var(--text-primary);
}

.auth-card .btn-secondary:hover {
  border-color: var(--neon-orange);
  color: var(--neon-orange);
}

.signup-footer-link {
  text-align: center;
  margin-top: 1.35rem;
  margin-bottom: 0;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-subtle);
  font-size: 0.88rem;
  color: var(--text-secondary);
}

.signup-footer-link a {
  color: var(--neon-orange);
  font-weight: 700;
}

.signup-footer-link a:hover {
  text-decoration: underline;
}

/* Confirmation View */
.signup-success-view {
  display: none;
  text-align: center;
  padding: 1.5rem 0 0.5rem;
}

.signup-success-view.visible {
  display: block;
}

.success-badge-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  margin: 0 auto 1.15rem;
  background: var(--neon-orange-soft);
  border: 2px solid var(--neon-orange);
  color: var(--neon-orange);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Dark Bootstrap Modal Styling */
.stride-bs-modal {
  background-color: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
}

.stride-bs-modal .modal-header {
  border-bottom: 1px solid var(--border-subtle);
}

.stride-bs-modal .modal-body {
  font-size: 0.88rem;
  color: var(--text-secondary);
}

.stride-bs-modal .modal-footer {
  border-top: 1px solid var(--border-subtle);
}

@media (max-width: 640px) {
  .auth-card {
    padding: 1.75rem 1.25rem;
  }
}

/* ==========================================================================
   SIGN UP PAGE LOGIC (signup.html — Pure Vanilla JavaScript + Bootstrap 5 Modal)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('signup-form');
  if (!form) return;

  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const nameEl = document.getElementById('signup-name');
  const emailEl = document.getElementById('signup-email');
  const passwordEl = document.getElementById('signup-password');
  const confirmEl = document.getElementById('signup-confirm-password');
  const termsEl = document.getElementById('terms-agree');

  const nameGroup = document.getElementById('group-signup-name');
  const emailGroup = document.getElementById('group-signup-email');
  const passwordGroup = document.getElementById('group-signup-password');
  const confirmGroup = document.getElementById('group-signup-confirm');
  const termsGroup = document.getElementById('group-terms');

  const strengthBar = document.getElementById('strength-bar');
  const ruleEls = {
    length: document.getElementById('rule-length'),
    upper: document.getElementById('rule-upper'),
    number: document.getElementById('rule-number'),
    symbol: document.getElementById('rule-symbol')
  };

  const successView = document.getElementById('signup-success-view');
  const welcomeMsgEl = document.getElementById('signup-welcome-msg');

  const termsModalEl = document.getElementById('terms-modal');
  const openTermsBtn = document.getElementById('open-terms-btn');
  const closeTermsBtn = document.getElementById('close-terms-modal');
  const acceptTermsBtn = document.getElementById('accept-terms-modal-btn');

  // Use Bootstrap 5 Modal API when available; graceful fallback if offline
  const bsTermsModal = (termsModalEl && window.bootstrap && window.bootstrap.Modal)
    ? new window.bootstrap.Modal(termsModalEl)
    : null;

  STRIDE_APP.bindPasswordToggle(document.getElementById('toggle-signup-password'), passwordEl);
  STRIDE_APP.bindPasswordToggle(document.getElementById('toggle-confirm-password'), confirmEl);

  function evaluatePassword(value) {
    return {
      length: value.length >= 8,
      upper: /[A-Z]/.test(value),
      number: /[0-9]/.test(value),
      symbol: /[^A-Za-z0-9]/.test(value)
    };
  }

  function updatePasswordStrength() {
    const checks = evaluatePassword(passwordEl.value);
    let metCount = 0;

    Object.keys(checks).forEach((key) => {
      const isMet = checks[key];
      if (isMet) metCount += 1;
      if (ruleEls[key]) {
        ruleEls[key].classList.toggle('met', isMet);
      }
    });

    const pct = (metCount / 4) * 100;
    strengthBar.style.width = `${pct}%`;
    if (metCount <= 1) {
      strengthBar.style.backgroundColor = 'var(--accent-red)';
    } else if (metCount <= 3) {
      strengthBar.style.backgroundColor = 'var(--accent-amber)';
    } else {
      strengthBar.style.backgroundColor = 'var(--accent-green)';
    }

    return metCount === 4;
  }

  function checkPasswordMatch() {
    if (!confirmEl.value) {
      STRIDE_APP.setFieldError(confirmGroup, confirmEl, false);
      return false;
    }
    const mismatch = passwordEl.value !== confirmEl.value;
    STRIDE_APP.setFieldError(confirmGroup, confirmEl, mismatch);
    return !mismatch;
  }

  nameEl.addEventListener('input', () => {
    if (nameEl.value.trim().length >= 2) {
      STRIDE_APP.setFieldError(nameGroup, nameEl, false);
    }
  });

  emailEl.addEventListener('input', () => {
    if (EMAIL_REGEX.test(emailEl.value.trim())) {
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
    }
  });

  passwordEl.addEventListener('input', () => {
    const allMet = updatePasswordStrength();
    if (allMet) {
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
    }
    if (confirmEl.value) {
      checkPasswordMatch();
    }
  });

  confirmEl.addEventListener('input', checkPasswordMatch);

  termsEl.addEventListener('change', () => {
    if (termsEl.checked) {
      STRIDE_APP.setFieldError(termsGroup, termsEl, false);
    }
  });

  function showTermsModal() {
    if (bsTermsModal) {
      bsTermsModal.show();
    } else if (termsModalEl) {
      termsModalEl.classList.add('show');
      termsModalEl.style.display = 'block';
      termsModalEl.setAttribute('aria-hidden', 'false');
    }
  }

  function hideTermsModal() {
    if (bsTermsModal) {
      bsTermsModal.hide();
    } else if (termsModalEl) {
      termsModalEl.classList.remove('show');
      termsModalEl.style.display = 'none';
      termsModalEl.setAttribute('aria-hidden', 'true');
    }
    if (openTermsBtn) openTermsBtn.focus();
  }

  if (openTermsBtn && termsModalEl) {
    openTermsBtn.addEventListener('click', showTermsModal);
  }

  if (closeTermsBtn && !bsTermsModal) {
    closeTermsBtn.addEventListener('click', hideTermsModal);
  }

  if (acceptTermsBtn) {
    acceptTermsBtn.addEventListener('click', () => {
      termsEl.checked = true;
      STRIDE_APP.setFieldError(termsGroup, termsEl, false);
      hideTermsModal();
    });
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let valid = true;

    const fullName = nameEl.value.trim();
    const emailVal = emailEl.value.trim();

    const nameInvalid = fullName.length < 2;
    STRIDE_APP.setFieldError(nameGroup, nameEl, nameInvalid);
    if (nameInvalid) valid = false;

    const emailInvalid = !EMAIL_REGEX.test(emailVal);
    STRIDE_APP.setFieldError(emailGroup, emailEl, emailInvalid);
    if (emailInvalid) valid = false;

    const passwordStrong = updatePasswordStrength();
    STRIDE_APP.setFieldError(passwordGroup, passwordEl, !passwordStrong);
    if (!passwordStrong) valid = false;

    const confirmInvalid = !confirmEl.value || passwordEl.value !== confirmEl.value;
    STRIDE_APP.setFieldError(confirmGroup, confirmEl, confirmInvalid);
    if (confirmInvalid) valid = false;

    const termsInvalid = !termsEl.checked;
    STRIDE_APP.setFieldError(termsGroup, termsEl, termsInvalid);
    if (termsInvalid) valid = false;

    if (!valid) {
      STRIDE_APP.showToast('Please fix the highlighted registration errors.', 'error');
      return;
    }

    const accounts = STRIDE_APP.readJsonStorage('stride_accounts', []);
    const filtered = accounts.filter((a) => a.email.toLowerCase() !== emailVal.toLowerCase());
    filtered.push({
      name: fullName,
      email: emailVal,
      createdAt: new Date().toISOString()
    });
    localStorage.setItem('stride_accounts', JSON.stringify(filtered));

    STRIDE_APP.setCurrentUser(
      {
        name: fullName,
        email: emailVal,
        role: 'Verified Member'
      },
      true
    );

    form.style.display = 'none';
    welcomeMsgEl.textContent = `Welcome to STRIDE, ${fullName}. Your account (${emailVal}) is ready.`;
    successView.classList.add('visible');
    STRIDE_APP.showToast('STRIDE account created successfully!', 'success');
  });
});

