args.Content:
/* ==========================================================================
   LOGIN PAGE STYLES (login.html + Bootstrap 5 Dark-Neon Theme Overrides)
   ========================================================================== */

.auth-wrapper {
  min-height: calc(100vh - 180px);
  display: flex;
  align-items: center;
  padding: 2.75rem 0;
}

.auth-card {
  width: 100%;
  max-width: 470px;
  margin: 0 auto;
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle) !important;
  border-radius: var(--radius-xl);
  padding: 2.4rem 2.1rem;
  box-shadow: var(--shadow-card);
  color: var(--text-primary);
  position: relative;
  overflow: hidden;
}

.auth-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--neon-orange), transparent);
}

.auth-header {
  text-align: center;
  margin-bottom: 1.75rem;
}

.auth-brand-mark {
  margin: 0 auto 1rem;
}

.auth-header h1 {
  font-size: clamp(1.5rem, 3vw, 1.85rem);
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 0.4rem;
}

.auth-header p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 0;
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

/* Override Bootstrap .form-control / .form-check defaults for STRIDE dark theme */
.auth-form .form-label {
  margin-bottom: 0;
}

.auth-form .form-control.form-input {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-primary);
  border-radius: var(--radius-md);
  padding: 0.82rem 1rem;
}

.auth-form .form-control.form-input::placeholder {
  color: var(--text-muted);
}

.auth-form .form-control.form-input:focus {
  background-color: var(--bg-surface);
  color: var(--text-primary);
  border-color: var(--neon-orange);
  box-shadow: 0 0 0 3px rgba(255, 90, 31, 0.18);
}

.form-group.error .form-control.form-input {
  border-color: var(--accent-red);
}

.auth-password-wrap {
  position: relative;
}

.auth-password-wrap .form-control.form-input {
  padding-right: 3rem;
}

.password-toggle-btn {
  position: absolute;
  right: 0.65rem;
  top: 50%;
  transform: translateY(-50%);
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: color var(--transition-fast), background var(--transition-fast);
}

.password-toggle-btn:hover,
.password-toggle-btn[aria-pressed='true'] {
  color: var(--neon-orange);
  background: var(--neon-orange-soft);
}

.auth-options-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  font-size: 0.84rem;
}

.text-action-link {
  color: var(--neon-orange);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  padding: 0;
}

.text-action-link:hover {
  text-decoration: underline;
}

.remember-check-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding-left: 0;
}

.remember-check-wrap .form-check-input {
  float: none;
  margin-left: 0;
  margin-top: 0;
  width: 1rem;
  height: 1rem;
  background-color: var(--bg-surface);
  border-color: var(--border-strong);
  cursor: pointer;
}

.remember-check-wrap .form-check-input:checked {
  background-color: var(--neon-orange);
  border-color: var(--neon-orange);
}

.remember-check-wrap .form-check-input:focus {
  box-shadow: 0 0 0 3px rgba(255, 90, 31, 0.2);
}

.remember-label {
  color: var(--text-secondary);
  cursor: pointer;
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  text-transform: uppercase;
  margin: 0.1rem 0;
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border-subtle);
}

/* Keep STRIDE primary/secondary/outline button branding above Bootstrap defaults */
.auth-card .btn-primary,
.stride-bs-modal .btn-primary {
  background-color: var(--neon-orange);
  border-color: var(--neon-orange);
  color: #0B0D12;
  font-weight: 700;
}

.auth-card .btn-primary:hover,
.auth-card .btn-primary:focus,
.stride-bs-modal .btn-primary:hover {
  background-color: var(--neon-orange-hover);
  border-color: var(--neon-orange-hover);
  color: #0B0D12;
}

.auth-card .btn-secondary {
  background-color: var(--bg-elevated);
  border-color: var(--border-strong);
  color: var(--text-primary);
}

.auth-card .btn-secondary:hover {
  border-color: var(--neon-orange);
  color: var(--neon-orange);
}

.auth-footer-cta {
  text-align: center;
  font-size: 0.88rem;
  color: var(--text-secondary);
}

.auth-footer-cta a {
  color: var(--neon-orange);
  font-weight: 700;
}

.auth-footer-cta a:hover {
  text-decoration: underline;
}

/* Post-Login Authenticated Panel */
.login-success-view {
  display: none;
  text-align: center;
  padding: 1rem 0 0.5rem;
}

.login-success-view.visible {
  display: block;
}

.vault-status-badge {
  width: 62px;
  height: 62px;
  margin: 0 auto 1rem;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.14);
  border: 2px solid var(--accent-green);
  color: var(--accent-green);
  display: flex;
  align-items: center;
  justify-content: center;
}

.vault-user-meta {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 1rem;
  margin: 1rem 0 1.4rem;
  font-size: 0.86rem;
  color: var(--text-secondary);
  text-align: left;
}

.vault-user-meta strong {
  color: var(--text-primary);
}

/* Dark Bootstrap Modal Styling */
.stride-bs-modal {
  background-color: var(--bg-card);
  color: var(--text-primary);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
}

.stride-bs-modal .modal-header {
  border-bottom: 1px solid var(--border-subtle);
}

@media (max-width: 640px) {
  .auth-card {
    padding: 1.75rem 1.25rem;
  }
}

/* ==========================================================================
   LOGIN PAGE LOGIC (login.html — Pure Vanilla JavaScript + Bootstrap 5 Modal)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('login-form');
  if (!form) return;

  const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const emailEl = document.getElementById('login-email');
  const passwordEl = document.getElementById('login-password');
  const keepLoggedInEl = document.getElementById('keep-logged-in');
  const togglePwdBtn = document.getElementById('toggle-login-password');
  const demoBtn = document.getElementById('demo-fill-btn');

  const emailGroup = document.getElementById('group-login-email');
  const passwordGroup = document.getElementById('group-login-password');

  const successView = document.getElementById('login-success-view');
  const vaultMetaEl = document.getElementById('vault-user-meta');
  const vaultSignoutBtn = document.getElementById('vault-signout-btn');

  const forgotBtn = document.getElementById('forgot-password-btn');
  const forgotModalEl = document.getElementById('forgot-modal');
  const closeForgotBtn = document.getElementById('close-forgot-modal');
  const forgotForm = document.getElementById('forgot-form');
  const forgotEmailEl = document.getElementById('forgot-email');
  const forgotEmailGroup = document.getElementById('group-forgot-email');

  // Use Bootstrap 5 Modal API when available; graceful fallback if offline
  const bsForgotModal = (forgotModalEl && window.bootstrap && window.bootstrap.Modal)
    ? new window.bootstrap.Modal(forgotModalEl)
    : null;

  STRIDE_APP.bindPasswordToggle(togglePwdBtn, passwordEl);

  function renderAuthState() {
    const activeUser = STRIDE_APP.getCurrentUser();
    if (activeUser && activeUser.email) {
      form.style.display = 'none';
      successView.classList.add('visible');
      vaultMetaEl.innerHTML = '';

      const row1 = document.createElement('div');
      row1.innerHTML = '<strong>Collector:</strong> ';
      row1.appendChild(document.createTextNode(activeUser.name || 'STRIDE Member'));

      const row2 = document.createElement('div');
      row2.innerHTML = '<strong>Email:</strong> ';
      row2.appendChild(document.createTextNode(activeUser.email));

      const row3 = document.createElement('div');
      row3.innerHTML = '<strong>Status:</strong> ';
      row3.appendChild(document.createTextNode(activeUser.role || 'Verified Collector'));

      vaultMetaEl.appendChild(row1);
      vaultMetaEl.appendChild(row2);
      vaultMetaEl.appendChild(row3);
    } else {
      successView.classList.remove('visible');
      form.style.display = 'flex';
    }
  }

  emailEl.addEventListener('input', () => {
    if (EMAIL_REGEX.test(emailEl.value.trim())) {
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
    }
  });

  passwordEl.addEventListener('input', () => {
    if (passwordEl.value.length >= 6) {
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
    }
  });

  if (demoBtn) {
    demoBtn.addEventListener('click', () => {
      emailEl.value = 'i263195@isb.nu.edu.pk';
      passwordEl.value = 'Stride2026!';
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
      STRIDE_APP.showToast('Demo credentials populated. Click Sign In to enter.', 'info');
    });
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const emailVal = emailEl.value.trim();
    const pwdVal = passwordEl.value;

    const emailInvalid = !EMAIL_REGEX.test(emailVal);
    const pwdInvalid = pwdVal.length < 6;

    STRIDE_APP.setFieldError(emailGroup, emailEl, emailInvalid);
    STRIDE_APP.setFieldError(passwordGroup, passwordEl, pwdInvalid);

    if (emailInvalid || pwdInvalid) {
      STRIDE_APP.showToast('Please check your email and password.', 'error');
      return;
    }

    const accounts = STRIDE_APP.readJsonStorage('stride_accounts', []);
    const matched = accounts.find((acc) => acc.email.toLowerCase() === emailVal.toLowerCase());
    const userName = matched
      ? matched.name
      : emailVal === 'i263195@isb.nu.edu.pk'
        ? 'Danyal Mehdi'
        : emailVal.split('@')[0];

    STRIDE_APP.setCurrentUser(
      {
        name: userName,
        email: emailVal,
        role: 'Verified Collector'
      },
      Boolean(keepLoggedInEl && keepLoggedInEl.checked)
    );

    STRIDE_APP.showToast(`Welcome back, ${userName}! Vault unlocked.`, 'success');
    renderAuthState();
  });

  if (vaultSignoutBtn) {
    vaultSignoutBtn.addEventListener('click', () => {
      STRIDE_APP.clearCurrentUser();
      form.reset();
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
      renderAuthState();
      STRIDE_APP.showToast('Signed out of your vault.', 'info');
    });
  }

  function showForgotModal() {
    forgotEmailEl.value = emailEl.value.trim();
    STRIDE_APP.setFieldError(forgotEmailGroup, forgotEmailEl, false);
    if (bsForgotModal) {
      bsForgotModal.show();
    } else if (forgotModalEl) {
      forgotModalEl.classList.add('show');
      forgotModalEl.style.display = 'block';
      forgotModalEl.setAttribute('aria-hidden', 'false');
    }
    setTimeout(() => forgotEmailEl.focus(), 150);
  }

  function hideForgotModal() {
    if (bsForgotModal) {
      bsForgotModal.hide();
    } else if (forgotModalEl) {
      forgotModalEl.classList.remove('show');
      forgotModalEl.style.display = 'none';
      forgotModalEl.setAttribute('aria-hidden', 'true');
    }
    if (forgotBtn) forgotBtn.focus();
  }

  if (forgotBtn && forgotModalEl) {
    forgotBtn.addEventListener('click', showForgotModal);
  }

  if (closeForgotBtn && !bsForgotModal) {
    closeForgotBtn.addEventListener('click', hideForgotModal);
  }

  if (forgotForm) {
    forgotForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const targetEmail = forgotEmailEl.value.trim();
      const invalid = !EMAIL_REGEX.test(targetEmail);
      STRIDE_APP.setFieldError(forgotEmailGroup, forgotEmailEl, invalid);
      if (invalid) return;

      hideForgotModal();
      STRIDE_APP.showToast(`Password reset instructions prepared for ${targetEmail}.`, 'success');
    });
  }

  window.addEventListener('stride:authchange', () => {
    if (!STRIDE_APP.getCurrentUser()) {
      form.reset();
      STRIDE_APP.setFieldError(emailGroup, emailEl, false);
      STRIDE_APP.setFieldError(passwordGroup, passwordEl, false);
    }
    renderAuthState();
  });

  renderAuthState();
});

