Write-Output ("BOOTSTRAP_CSS=" + ($loginHtml -match 'bootstrap@5\.3\.3/dist/css/bootstrap\.min\.css') + " | BOOTSTRAP_JS=" + ($loginHtml -match 'bootstrap@5\.3\.3/dist/js/bootstrap\.bundle\.min\.js') + " | SIGNUP_LINK=" + ($loginHtml -match 'href="signup\.html"'))

$edge = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
$port = 9233
$tmpProfile = Join-Path $env:TEMP "stride_login_cdp_$PID"
New-Item -ItemType Directory -Force -Path $tmpProfile | Out-Null
$proc = Start-Process -FilePath $edge -ArgumentList @('--headless=new','--disable-gpu',"--remote-debugging-port=$port","--user-data-dir=$tmpProfile",'about:blank') -PassThru

try {
  $targets = $null
  for ($i = 0; $i -lt 30; $i++) {
    Start-Sleep -Milliseconds 250
    try { $targets = Invoke-RestMethod "http://127.0.0.1:$port/json/list"; if ($targets.Count -gt 0) { break } } catch {}
  }
  $pageTarget = $targets | Where-Object { $_.type -eq 'page' } | Select-Object -First 1
  $ws = [System.Net.WebSockets.ClientWebSocket]::new()
  $ct = [System.Threading.CancellationToken]::None
  $ws.ConnectAsync([Uri]$pageTarget.webSocketDebuggerUrl, $ct).GetAwaiter().GetResult()
  $script:msgId = 0
  function Invoke-Cdp($method, $params = @{}) {
    $script:msgId++
    $id = $script:msgId
    $json = (@{ id = $id; method = $method; params = $params } | ConvertTo-Json -Depth 10 -Compress)
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
    $ws.SendAsync([ArraySegment[byte]]::new($bytes), [System.Net.WebSockets.WebSocketMessageType]::Text, $true, $ct).GetAwaiter().GetResult()
    $buf = New-Object byte[] 65536
    while ($true) {
      $ms = New-Object System.IO.MemoryStream
      do {
        $res = $ws.ReceiveAsync([ArraySegment[byte]]::new($buf), $ct).GetAwaiter().GetResult()
        $ms.Write($buf, 0, $res.Count)
      } while (-not $res.EndOfMessage)
      $obj = ([System.Text.Encoding]::UTF8.GetString($ms.ToArray())) | ConvertFrom-Json
      if ($obj.id -eq $id) { return $obj }
    }
  }
  function Eval-Js($expr) {
    $r = Invoke-Cdp 'Runtime.evaluate' @{ expression = $expr; returnByValue = $true; awaitPromise = $true }
    if ($r.result.exceptionDetails) { throw "JS Exception: $($r.result.exceptionDetails.text)" }
    return $r.result.result.value
  }

  Invoke-Cdp 'Page.enable' | Out-Null
  Invoke-Cdp 'Runtime.enable' | Out-Null
  $uri = ([System.Uri](Join-Path $root 'html\login.html')).AbsoluteUri
  Invoke-Cdp 'Page.navigate' @{ url = $uri } | Out-Null
  Start-Sleep -Milliseconds 1200

  Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{ width = 1280; height = 800; deviceScaleFactor = 1; mobile = $false } | Out-Null
  Start-Sleep -Milliseconds 150
  $desk = Eval-Js "({ sw: document.documentElement.scrollWidth, iw: window.innerWidth, bsLoaded: Boolean(window.bootstrap && window.bootstrap.Modal) })"

  Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{ width = 375; height = 812; deviceScaleFactor = 2; mobile = $true } | Out-Null
  Start-Sleep -Milliseconds 150
  $mob = Eval-Js "({ sw: document.documentElement.scrollWidth, iw: window.innerWidth })"

  $flow = Eval-Js @"
(() => {
  localStorage.clear(); sessionStorage.clear();

  // 1. Show/hide password toggle
  const pwd = document.getElementById('login-password');
  const pwdBtn = document.getElementById('toggle-login-password');
  pwdBtn.click();
  const pwdShown = pwd.type === 'text' && pwdBtn.getAttribute('aria-pressed') === 'true';
  pwdBtn.click();
  const pwdHidden = pwd.type === 'password' && pwdBtn.getAttribute('aria-pressed') === 'false';

  // 2. Invalid submit shows clear error messages
  document.getElementById('login-email').value = 'bad-email';
  pwd.value = '123';
  document.querySelector('#login-form button[type="submit"]').click();
  const emailErr = getComputedStyle(document.getElementById('login-email-error')).display !== 'none';
  const pwdErr = getComputedStyle(document.getElementById('login-password-error')).display !== 'none';

  // 3. Demo fill + Sign In -> Vault Unlocked + Sign Out
  document.getElementById('demo-fill-btn').click();
  const demoEmail = document.getElementById('login-email').value;
  document.querySelector('#login-form button[type="submit"]').click();
  const vaultUnlocked = document.getElementById('login-success-view').classList.contains('visible');
  const vaultText = document.getElementById('vault-user-meta').textContent;
  document.getElementById('vault-signout-btn').click();
  const signedOut = !document.getElementById('login-success-view').classList.contains('visible');

  // 4. Forgot password form validation
  document.getElementById('forgot-email').value = 'invalid';
  document.getElementById('forgot-form').dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
  const forgotErr = getComputedStyle(document.getElementById('forgot-email-error')).display !== 'none';

  const signupLinks = document.querySelectorAll('a[href="signup.html"]').length;

  return { pwdShown, pwdHidden, emailErr, pwdErr, demoEmail, vaultUnlocked, vaultText, signedOut, forgotErr, signupLinks };
})()
"@
  Write-Output ("DESKTOP=" + ($desk | ConvertTo-Json -Compress))
  Write-Output ("MOBILE=" + ($mob | ConvertTo-Json -Compress))
  Write-Output ("FLOW=" + ($flow | ConvertTo-Json -Compress))
  $ws.Dispose()
} finally {
  if ($proc -and -not $proc.HasExited) { Stop-Process -Id $proc.Id -Force }
  Start-Sleep -Milliseconds 200
  Remove-Item -Recurse -Force $tmpProfile -ErrorAction SilentlyContinue
}

