  email.value = 'ali.raza@example.com';
  pwd.value = 'WrongPass1!';
  submitBtn.click();
  const wrongPwdErr = errEl.textContent;
  const blockedWrongPwd = !document.getElementById('login-success-view').classList.contains('visible');

  // C. Registered email + correct password + Remember me checked
  pwd.value = 'Sneaker2026!';
  document.getElementById('keep-logged-in').checked = true;
  submitBtn.click();
  const unlockedRemember = document.getElementById('login-success-view').classList.contains('visible');
  const localStored = Boolean(localStorage.getItem('stride_user'));
  const vaultInfo = document.getElementById('vault-user-meta').textContent;

  // D. Sign out + Remember me unchecked -> sessionStorage
  document.getElementById('vault-signout-btn').click();
  email.value = 'ali.raza@example.com';
  pwd.value = 'Sneaker2026!';
  document.getElementById('keep-logged-in').checked = false;
  submitBtn.click();
  const sessionStored = Boolean(sessionStorage.getItem('stride_user')) && !localStorage.getItem('stride_user');

  // E. Toggle password + Forgot link + Signup link
  document.getElementById('vault-signout-btn').click();
  document.getElementById('toggle-login-password').click();
  const pwdToggled = pwd.type === 'text';

  return {
    unknownErr, blockedUnknown,
    wrongPwdErr, blockedWrongPwd,
    unlockedRemember, localStored, vaultInfo,
    sessionStored, pwdToggled,
    forgotHref: document.getElementById('forgot-password-btn').getAttribute('href'),
    signupLinks: document.querySelectorAll('a[href="signup.html"]').length
  };
})()
"@

  Write-Output ("SIGNUP_E2E=" + ($signupOut | ConvertTo-Json -Compress))
  Write-Output ("LOGIN_E2E=" + ($loginOut | ConvertTo-Json -Compress))
  Write-Output ("RESP=desk:" + $desk.sw + "/" + $desk.iw + " mob:" + $mob.sw + "/" + $mob.iw)
  $ws.Dispose()
} finally {
  if ($proc -and -not $proc.HasExited) { Stop-Process -Id $proc.Id -Force }
  Start-Sleep -Milliseconds 200
  Remove-Item -Recurse -Force $tmpProfile -ErrorAction SilentlyContinue
}
